import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { parseGameConfig, runSimulation, parseInputLog } from '../src/index.js';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '../../..');

/**
 * Replays the published test vectors through sim-core-ts and asserts an exact
 * match. The vectors are committed DATA generated by the C# core; this is the
 * determinism gate that turns "client and server agree" into a test. The Unity
 * EditMode suite replays the same file through sim-core-cs.
 */
const vectorPath = resolve(repoRoot, 'Backend/testvectors/vectors.tsv');
const lines = readFileSync(vectorPath, 'utf8').split('\n');

const gameText = readFileSync(resolve(repoRoot, 'Backend/config/redline.game.json'), 'utf8');
const { config } = parseGameConfig(gameText);

interface Vector {
  seed: string;
  maxTicks: number;
  inputs: string;
  outcome: string;
  score: number;
  scoreUnits: bigint;
  endTick: number;
  distance: number;
  finalLane: number;
  rejected: number;
}

const vectors: Vector[] = [];
let headerHash: string | null = null;
for (const line of lines) {
  if (line.startsWith('# configHash:')) headerHash = line.slice('# configHash:'.length).trim();
  if (line.length === 0 || line[0] === '#') continue;
  const f = line.split('\t');
  vectors.push({
    seed: f[0]!,
    maxTicks: Number(f[1]),
    inputs: f[2]!,
    outcome: f[3]!,
    score: Number(f[4]),
    scoreUnits: BigInt(f[5]!),
    endTick: Number(f[6]),
    distance: Number(f[7]),
    finalLane: Number(f[8]),
    rejected: Number(f[9]),
  });
}

describe('test vector parity', () => {
  it('the vector file was recorded under the current config', () => {
    expect(headerHash).toBe(config.configHash);
  });

  it('covers at least 20 runs including banked and crashed', () => {
    expect(vectors.length).toBeGreaterThanOrEqual(20);
    expect(vectors.some((v) => v.outcome === 'Banked')).toBe(true);
    expect(vectors.some((v) => v.outcome === 'Crashed')).toBe(true);
  });

  for (const [i, v] of vectors.entries()) {
    it(`vector ${i} (seed ${v.seed}, ${v.inputs}) reproduces exactly`, () => {
      const r = runSimulation(config, {
        seed: v.seed,
        events: parseInputLog(v.inputs),
        maxRunTicks: v.maxTicks,
      });
      expect(r.outcome).toBe(v.outcome);
      expect(r.score).toBe(v.score);
      expect(r.scoreUnits).toBe(v.scoreUnits);
      expect(r.endTick).toBe(v.endTick);
      expect(r.distance).toBe(v.distance);
      expect(r.finalLane).toBe(v.finalLane);
      expect(r.rejectedInputs).toBe(v.rejected);
    });
  }
});
